import pandas as pd

def exposures(book):
    value = book["price"] * book["qty"]
    long = value[book["qty"] > 0].sum()
    short = value[book["qty"] < 0].sum()
    return {"long": round(float(long), 2), "short": round(float(short), 2),
            "gross": round(float(long - short), 2), "net": round(float(long + short), 2)}

import pandas as pd

def fills_report(ids, ticker, side, qty, price, a, b):
    fills = pd.DataFrame({"ticker": ticker, "side": side, "qty": qty, "price": price}, index=ids)
    fills.loc[fills["side"] == "sell", "qty"] *= -1          # one .loc call writes into fills itself
    fills["value"] = fills["qty"] * fills["price"]          # NaN where the price is missing
    span = fills.loc[a:b, "value"]                          # labels, both ends kept, in row order
    confirmed = fills["value"].dropna()
    return {"fills": fills, "span": span,
            "last": confirmed.index[-1],                    # by position: the last row left
            "net": float(confirmed.sum())}
